#include <stdio.h>

int main(void) {
    int power = 17, modules = 5;
    printf("Each: %d\n", power / modules);
    printf("Left over: %d\n", power % modules);
    printf("Exact: %.2f\n", (double)power / modules);
    return 0;
}

