#include <stdio.h>

int main(void) {
    int status = 5;              // binary 101: switches 0 and 2 on
    printf("%d\n", status | 2);  // switch 1 on: 111
    printf("%d\n", status & 4);  // keep switch 2: 100
    printf("%d\n", status ^ 1);  // flip switch 0: 100
    printf("%d\n", 1 << 3);      // only switch 3: 1000
    return 0;
}

